		$this->assertEquals([
    '5' => [
		        'id' => 5,
		    ],
		    '4' => [
		        'id' => 4,
		    ],
		    '3' => [
		        'id' => 3,
		    ],
		    '2' => [
		        'id' => 2,
		    ],
		    '1' => [
		        'id' => 1,
		    ],
], $array);
	}

	public function testAlphabeticalOrdering() {
		$array = [
    'f' => [
		        'name' => 'Foo',
		    ],
		    'v' => [
		        'name' => 'Value',
		    ],
		    't' => [
